window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/humanas_2023.js"]=[{"title":"O sertão como memória afetiva","steps":["O bordado define sertão como a avó bordando caminhos com linhas coloridas.","Fotografia, gesto de costurar e caminhos relacionam espaço e experiência familiar.","A definição se apoia em vivências e itinerários socioafetivos, C, não numa delimitação cartográfica objetiva."],"alternatives":{"A":"A obra não apresenta um roteiro para organizar visitas turísticas.","B":"Não são descritos movimentos holísticos ou práticas terapêuticas.","C":"A memória da avó e os caminhos bordados vinculam o lugar a experiências afetivas.","D":"A definição não estabelece limites políticos ou fronteiras precisas.","E":"A costura tem valor de memória; não se discute uma atividade por seu interesse econômico."},"takeaway":"O conceito geográfico de lugar envolve experiência e pertencimento, além da localização.","key":"humanas:H557","area":"humanas","year":2023,"number":46,"answer":"C","subject":"Geografia","topic":"Cartografia, paisagem e tecnologias geográficas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Letramento modifica relações familiares","steps":["A comparação entre épocas destaca que as moças antes não escreviam bilhetes.","Saber escrever amplia possibilidades de comunicação e interfere no controle familiar dos contatos.","O fator apontado é práticas de letramento associadas a transformação cultural, D, não uma reforma educacional específica."],"alternatives":{"A":"O trecho não descreve migração ou mobilidade entre regiões.","B":"Ir à missa é parte do costume antigo, não o fator que explica a mudança.","C":"Não há imigração estrangeira ou valorização de um idioma como causa.","D":"A escrita de bilhetes mostra a relação entre alfabetização e novas práticas sociais.","E":"Não são apresentados um programa pedagógico ou mudanças legais na organização do ensino."},"takeaway":"Relacione uma prática cultural ao efeito social concreto que o documento lhe atribui.","key":"humanas:H061","area":"humanas","year":2023,"number":47,"answer":"D","subject":"História do Brasil","topic":"Império e independência","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A apropriação do território ameaça modos de vida","steps":["O texto enumera privatização de bens comuns, imposição de saberes e formas de violência.","Esses processos subordinam os camponeses ao agronegócio e ao mercado.","A consequência é um cerco às condições de reprodução da vida camponesa, A, não a vitimização dos grandes proprietários."],"alternatives":{"A":"A apropriação dos recursos e a violência comprometem a manutenção dos modos de vida locais.","B":"O trecho critica a força dos grandes agentes, não um descaso com os latifundiários.","C":"A questão não se centra na organização sindical de assalariados.","D":"O problema não é desrespeito a governantes, mas relações desiguais de controle territorial.","E":"O empresariado aparece como parte da expansão dominante, não como o grupo assediado."},"takeaway":"Territorialização envolve poder e acesso a recursos, não apenas a área física ocupada.","key":"humanas:H303","area":"humanas","year":2023,"number":48,"answer":"A","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Migração incentivada como estratégia de controle","steps":["Xinjiang é estratégica por fronteiras, recursos e infraestrutura.","O governo incentiva a migração Han para alterar a composição populacional.","Nos textos, a política ajuda a assegurar a integridade territorial, E, reforçando o controle de uma região sensível."],"alternatives":{"A":"O objetivo não é definido como simples ocupação de zonas rurais.","B":"Não se apresenta ampliação da liberdade religiosa como finalidade da mudança populacional.","C":"A ação é do governo central e não indica descentralização administrativa.","D":"Aumentar a proporção de uma etnia não é uma medida descrita como incentivo à pluralidade.","E":"O vínculo entre população e área estratégica aponta para manutenção do controle territorial."},"takeaway":"Políticas demográficas também podem ser instrumentos geopolíticos, não apenas respostas ao crescimento populacional.","key":"humanas:H487","area":"humanas","year":2023,"number":49,"answer":"E","subject":"Geografia","topic":"Demografia e migrações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Recontar a história além do olhar colonizador","steps":["A plataforma dá visibilidade a heranças africanas e a figuras encobertas.","O objetivo é não reduzir trajetórias negras à condição de escravização.","A iniciativa questiona o privilégio da perspectiva europeia: crítica ao eurocentrismo, E."],"alternatives":{"A":"A proposta não é restaurar costumes por serem tradicionais, mas revisar um enquadramento histórico.","B":"Antropocentrismo contrapõe centralidade humana e divina; não é o eixo do texto.","C":"A iniciativa contesta uma perspectiva hierarquizante, não propõe superioridade de uma etnia.","D":"Não há proposta de colocar a divindade no centro da explicação histórica.","E":"Valorizar protagonistas e heranças afro-brasileiras contesta a exclusividade do olhar colonizador europeu."},"takeaway":"Revisar narrativas não é apagar a escravidão: é reconhecer sujeitos e experiências além dela.","key":"humanas:H784","area":"humanas","year":2023,"number":50,"answer":"E","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma promessa confrontada com conflitos territoriais","steps":["A declaração apoia um lar nacional judeu e promete não prejudicar direitos de comunidades não judaicas.","O resultado histórico do processo envolve disputas pelo território e dificuldades de garantir essas condições simultaneamente.","O fracasso destacado é mediar conflitos territoriais, C, sem reduzir o problema a liberdade religiosa isolada."],"alternatives":{"A":"Bem-estar social é uma expressão ampla e não nomeia o conflito específico do documento.","B":"O texto não formula como objetivo principal obter apoio religioso muçulmano.","C":"A tensão entre projetos nacionais e direitos de populações da mesma área é territorial.","D":"Cooperação regional é genérica em relação ao compromisso e ao resultado destacados.","E":"Não se apresenta combate a governos autocráticos como finalidade da declaração."},"takeaway":"Em documentos diplomáticos, compare a promessa expressa com a dimensão histórica que ela não conseguiu resolver.","key":"humanas:H358","area":"humanas","year":2023,"number":51,"answer":"C","subject":"Geografia","topic":"Geopolítica e globalização","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Consciência e responsabilidade pela transformação","steps":["Freire rejeita a ideia de que a pessoa seja apenas produto de determinações.","O segundo texto afirma que desigualdades são históricas e podem ser transformadas.","Consciência da realidade e responsabilidade ética fundamentam participação sociopolítica, A, não mera adaptação individual."],"alternatives":{"A":"A ação responsável diante de estruturas sociais liga educação e participação política.","B":"A definição estética de uma cultura não é o problema central dos dois textos.","C":"A finalidade não é preparar estudantes apenas para competir economicamente.","D":"A proposta admite transformar instituições e relações, não só manter o sistema escolar.","E":"Mobilidade individual não resume a dimensão coletiva da transformação defendida."},"takeaway":"Não confunda reconhecer condicionamentos sociais com afirmar que toda ação já está determinada por eles.","key":"humanas:H621","area":"humanas","year":2023,"number":52,"answer":"A","subject":"Filosofia","topic":"Ética e filosofia política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Montanhas erguidas pela convergência","steps":["O Himalaia se relaciona à colisão entre a placa Indiana e a Eurasiática.","A compressão da crosta produz dobramentos e soerguimento, ainda ativos.","O mecanismo responsável é encontro de placas tectônicas, B, não erosão ou simples deposição de sedimentos."],"alternatives":{"A":"A cordilheira não é explicada por empilhamento de derrames vulcânicos.","B":"A convergência e colisão de placas geram compressão e elevação da crosta.","C":"Intemperismo químico altera e desgasta rochas, não explica a elevação tectônica principal.","D":"Sedimentação eólica não forma a grande cordilheira pela dinâmica descrita.","E":"Derreter geleiras não é o mecanismo de formação e crescimento apresentado."},"takeaway":"Separe construção tectônica do relevo dos processos externos que o desgastam e remodelam.","key":"humanas:H524","area":"humanas","year":2023,"number":53,"answer":"B","subject":"Geografia","topic":"Geologia, relevo e solos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A experiência corporal contrasta com o dualismo","steps":["A primeira hipótese separa pensamento de qualquer fragmento material.","Na experiência da raiva, o autor percebe o sentimento no corpo, não fora dele.","O contraponto cartesiano é a visão dualista entre substância pensante e extensa, A, sem reduzir todo o pensamento cartesiano a negar qualquer interação."],"alternatives":{"A":"A distinção entre pensamento e extensão é a formulação cartesiana contrastada.","B":"Naturalismo não descreve o dualismo que separa espírito e matéria.","C":"Realismo é amplo e não nomeia a divisão específica discutida.","D":"Idealismo não expressa com a mesma precisão a distinção de duas substâncias.","E":"Intencionalidade não é a característica cartesiana mobilizada nessa oposição."},"takeaway":"No dualismo mente/corpo, identifique a distinção ontológica antes de discutir como as partes se relacionam.","key":"humanas:H666","area":"humanas","year":2023,"number":54,"answer":"A","subject":"Filosofia","topic":"Filosofia moderna: razão, ciência e conhecimento","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O lazer reproduz a lógica do trabalho","steps":["Os autores dizem que a diversão se organiza no mesmo sistema mecanizado de produção.","A pessoa busca descanso, mas consome mercadorias culturais que reproduzem a lógica de sua jornada.","A concepção explicitada é consumo de produtos culturais do sistema capitalista, A."],"alternatives":{"A":"A diversão aparece como consumo integrado ao mesmo processo produtivo que organiza o trabalho.","B":"O trecho questiona, em vez de celebrar, o desenvolvimento livre das potencialidades.","C":"Recuperar-se para voltar ao trabalho aparece, mas não esgota a crítica da reprodução produtiva.","D":"Necessidades artificiais relacionam-se à crítica mais ampla, mas não são a formulação central do trecho.","E":"Organizar ócio e prazer é genérico e omite sua ligação ao sistema de produção."},"takeaway":"Em indústria cultural, observe a continuidade entre trabalho, mercadoria e entretenimento.","key":"humanas:H696","area":"humanas","year":2023,"number":55,"answer":"A","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Poder político não é um superpoder","steps":["O gênio entende poder como força, raio X ou telepatia.","A personagem corrige a interpretação: quer poder político.","A charge desloca a fantasia para a possibilidade de participar de decisões coletivas, C, e não demonstra por si adesão a um partido."],"alternatives":{"A":"Não há manifestação de revolta individual como núcleo da sequência.","B":"O desejo é pessoal na forma da fala, mas o conteúdo específico é poder decisório político.","C":"O acesso à decisão pública é o sentido político que se opõe aos poderes fantásticos.","D":"Querer poder se opõe à permanência passiva diante das decisões sociais.","E":"Nenhum partido ou acordo partidário é mencionado na charge."},"takeaway":"Leia a mudança de sentido que constrói o humor e relacione-a ao conceito solicitado.","key":"humanas:H819","area":"humanas","year":2023,"number":56,"answer":"C","subject":"Sociologia","topic":"Poder, Estado e política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pedir perdão não dá direito a recebê-lo","steps":["O pedido reconhece a possibilidade de recusa.","Quem foi ofendido mantém autonomia para decidir, sem obrigação automática de absolver.","O fundamento está em relações interpessoais entre indivíduos autônomos, E, não em predestinação ou imposição externa."],"alternatives":{"A":"A recusa não é definida como desejo de dominar quem pede perdão.","B":"O texto não condiciona a decisão à vontade divina.","C":"Predestinação eliminaria a liberdade de decisão que a passagem preserva.","D":"Conhecimento empírico não é o critério que fundamenta o direito de aceitar ou recusar.","E":"O perdão envolve uma decisão livre do outro, não uma prestação devida a quem o solicita."},"takeaway":"Diferencie reconhecimento de um pedido e obrigação de atendê-lo; autonomia também permite recusar.","key":"humanas:H697","area":"humanas","year":2023,"number":57,"answer":"E","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma tradição pode ser retomada e transformada","steps":["A cavalgada se vinculava ao transporte rural e à devoção à santa.","A expansão dos automóveis interrompeu a prática, depois retomada com novos participantes e contextos.","A continuidade da crença articula elementos tradicionais e modernos, A, não uma ordem papal."],"alternatives":{"A":"O rito religioso permanece como referência, enquanto transporte, participantes e contexto se alteram.","B":"Não há determinação do papa para extinguir ou restaurar o evento.","C":"O relato não atribui a transformação a fundamentos estéticos de cerimônia clerical.","D":"A participação em cavalgada não é descrita como imposição eclesiástica esportiva.","E":"Não há ordem paroquial nem discurso filosófico como causa demonstrada."},"takeaway":"Tradição não é imobilidade: práticas podem desaparecer, ser retomadas e assumir novas funções.","key":"humanas:H785","area":"humanas","year":2023,"number":58,"answer":"A","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Etiqueta marca pertencimento de classe","steps":["O garfo aparece primeiro entre grupos de posição social elevada.","Seu caráter de luxo, inclusive com materiais preciosos, reforça a distinção entre quem o usa e os demais.","A etiqueta funciona como distinção de classes, A; higiene não é o argumento desenvolvido."],"alternatives":{"A":"O acesso restrito e o uso nas cortes fazem do utensílio uma marca de posição social.","B":"O trecho não justifica a adoção principalmente pela prevenção de doenças.","C":"A origem italiana não significa que o princípio da etiqueta seja exaltar toda a cultura mediterrânea.","D":"A prática se difunde na Idade Moderna e não é descrita como consagração medieval.","E":"A disseminação material é contexto; o princípio social destacado é a diferenciação."},"takeaway":"Hábitos que parecem apenas pessoais podem comunicar posição, prestígio e pertencimento social.","key":"humanas:H786","area":"humanas","year":2023,"number":59,"answer":"A","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Controle de bens também é violência","steps":["As condutas atingem documentos, dinheiro, trabalho e pertences da mulher.","O controle desses recursos limita autonomia e condições materiais de vida.","Na Lei Maria da Penha, a categoria correspondente é violência patrimonial, D, e não um simples desacordo conjugal."],"alternatives":{"A":"Difamação atinge reputação; os exemplos tratam diretamente de bens e recursos.","B":"Desvio comportamental é vago e não identifica a categoria jurídica pertinente.","C":"Preconceito pode integrar a violência, mas não nomeia o dano material descrito.","D":"Retenção, destruição e controle abusivo de recursos caracterizam violência patrimonial.","E":"Chamar as ações de mero desentendimento minimiza condutas previstas como violência."},"takeaway":"Não reduza violência doméstica à agressão física: direitos e recursos materiais também podem ser atacados.","key":"humanas:H733","area":"humanas","year":2023,"number":60,"answer":"D","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A automação esconde trabalho humano","steps":["O texto contrapõe a aparência mágica da IA ao trabalho de linguistas subcontratados.","Baixos salários e horas não pagas mostram quem sustenta o serviço sem receber visibilidade correspondente.","A crítica é à invisibilidade do profissional, E; não se afirma que o sistema funcione sem pessoas."],"alternatives":{"A":"O ponto crítico não é oferecer mais funções profissionais, mas ocultar o trabalho que as viabiliza.","B":"A distribuição global da equipe não é descrita principalmente como migração populacional.","C":"Baixos salários e imposição de horas extras não caracterizam autonomia do trabalhador.","D":"O trecho critica a ocultação do trabalho precário, não analisa a concentração empresarial da produção.","E":"A aparência de automação apaga o reconhecimento do trabalho humano precário por trás do serviço."},"takeaway":"Pergunte quais trabalhos permanecem necessários quando uma tecnologia parece funcionar sozinha.","key":"humanas:H760","area":"humanas","year":2023,"number":61,"answer":"E","subject":"Sociologia","topic":"Trabalho, capitalismo e desigualdades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma rivalidade de Estados e ideologias","steps":["Propaganda e símbolos nacionais são usados por governos dos dois lados da fronteira.","A divisão coreana se vincula aos antagonismos político-ideológicos da Guerra Fria.","C explica as origens da competição; não se trata de conflito étnico entre povos distintos."],"alternatives":{"A":"Símbolos culturais participam da disputa, mas o contexto de origem é político-estatal.","B":"A rivalidade não é explicada por oposição racial ou étnica entre os coreanos.","C":"Estados associados a projetos políticos distintos competem por legitimidade e influência.","D":"Empresas privadas não são os agentes responsáveis pelos alto-falantes e mastros descritos.","E":"Não se relatam mobilizações ambientais ou protestos ecológicos."},"takeaway":"Diferencie a linguagem simbólica de uma disputa de suas causas histórico-políticas.","key":"humanas:H359","area":"humanas","year":2023,"number":62,"answer":"C","subject":"Geografia","topic":"Geopolítica e globalização","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Objetos atravessam oceanos e inspiram arte","steps":["A circulação de porcelanas, gravuras e tecidos chineses chega à sociedade colonial enriquecida.","Os motivos desses objetos são apropriados em igrejas do barroco mineiro.","O intercâmbio transcontinental, B, permite a combinação artística; não é preciso supor uma ordem estatal de padronização."],"alternatives":{"A":"A arquitetura é suporte de parte das obras, não a condição que faz os motivos chineses chegarem.","B":"A circulação entre continentes coloca objetos e referências estéticas em contato.","C":"Dependência econômica é uma categoria ampla que não explica a transmissão cultural descrita.","D":"Não há intervenção estatal impondo as chinesices no texto.","E":"Padrão estético é um resultado reconhecível, mas não a condição material da circulação."},"takeaway":"Bens comerciais também circulam como referências culturais e podem ser recriados em outros contextos.","key":"humanas:H191","area":"humanas","year":2023,"number":63,"answer":"B","subject":"História Geral","topic":"Idade Moderna: Renascimento, Reforma e absolutismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma denúncia dos efeitos da exploração predatória","steps":["O discurso relaciona aquecimento, perda de animais, rios degradados e alterações nas plantações.","Esse conjunto aponta para formas de exploração que comprometem os sistemas ambientais.","A alternativa D nomeia o problema, enquanto as demais se aproximam de práticas ou propostas de manejo e mitigação."],"alternatives":{"A":"Manejo tradicional não é apresentado como causa dos danos denunciados.","B":"Reciclagem de resíduos não explica a origem do conjunto de perdas.","C":"Consumo consciente é uma resposta possível, não o problema mencionado.","D":"Exploração predatória compromete clima, biodiversidade e condições de vida.","E":"Reaproveitamento energético não é caracterizado como responsável pelos efeitos descritos."},"takeaway":"Veja se a pergunta pede causa do problema ou uma prática que poderia enfrentá-lo.","key":"humanas:H448","area":"humanas","year":2023,"number":64,"answer":"D","subject":"Geografia","topic":"Climatologia e biomas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reconhecer uma autora antes invisibilizada","steps":["O trabalho de Lina é omitido e o elogio se concentra no marido.","O reconhecimento posterior contrasta com a desigualdade de atribuição de mérito entre mulher e homem.","A mudança se relaciona às mobilizações por equidade de gênero, A, e não somente ao direito ao voto."],"alternatives":{"A":"A correção da invisibilidade profissional feminina se relaciona à busca de equidade de gênero.","B":"Não se relata proibição de emitir opiniões como o núcleo do apagamento.","C":"O reconhecimento de autoria arquitetônica não se limita à conquista do sufrágio.","D":"Igualdade de oportunidade é ampla, mas o caso é especificamente uma assimetria de gênero.","E":"Reciprocidade é genérica e não nomeia o eixo estrutural da desigualdade apresentada."},"takeaway":"Observe quem recebe crédito pelo trabalho e quais relações sociais explicam esse reconhecimento desigual.","key":"humanas:H734","area":"humanas","year":2023,"number":65,"answer":"A","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A fome reaparece em tempos diferentes","steps":["O primeiro relato apresenta a dor materna diante da falta de alimento.","O segundo atualiza experiência semelhante com desemprego e insuficiência de recursos.","A aproximação evidencia recorrência da miséria, A, não uma economia imutável ou superação da escassez."],"alternatives":{"A":"A distância entre as datas contrasta com a persistência de fome e precariedade.","B":"Os textos não descrevem planejamento ou organização de serviços de saúde.","C":"A necessidade continua sem atendimento; não se mostra uma vitória contra a fome.","D":"A repetição do sofrimento não significa que a economia inteira permaneceu igual.","E":"Os relatos denunciam a carência, sem transformá-la em experiência idealizada ou desejável."},"takeaway":"Uma permanência social pode atravessar contextos econômicos diferentes: persistência não é identidade de todos os fatores.","key":"humanas:H394","area":"humanas","year":2023,"number":66,"answer":"A","subject":"Geografia","topic":"Urbanização e espaço urbano","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Produzir sem eliminar todo o dossel","steps":["A cabruca aproveita a tolerância do cacau à sombra de árvores nativas.","O sistema mantém elementos florestais e conserva mais biodiversidade que monoculturas e pastagens comparadas.","É exemplo de uso sustentável dos recursos naturais, B, sem equivaler a ausência completa de impacto."],"alternatives":{"A":"O cacau não é apresentado como uma lavoura temporária recém-difundida.","B":"O cultivo combina produção agrícola com manutenção de parte da estrutura florestal.","C":"Não se trata de pecuária nem de ampliação tecnológica do confinamento.","D":"A prática não padroniza a dieta de povos tradicionais no relato.","E":"O destaque é ecológico-produtivo, não uma modernização dos transportes."},"takeaway":"Sustentabilidade deve ser avaliada comparativamente e pelo manejo, não como impacto absolutamente nulo.","key":"humanas:H304","area":"humanas","year":2023,"number":67,"answer":"B","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Moradia e produção transformam o ambiente","steps":["O trecho associa moradias precárias a enchentes de maré, insetos e mau cheiro.","A lavagem de couros e peles contamina o ambiente, mata peixes e altera as relações locais.","A alternativa C é a que reconhece a interferência e transformação do espaço geográfico, em vez de conservação ou equilíbrio."],"alternatives":{"A":"A cena é de urbanização precária e impactos, não de conservação rural.","B":"Não se observa expansão protetora de vegetação ciliar.","C":"Ocupação, atividade produtiva e poluição alteram o ambiente e o espaço vivido.","D":"A mortandade de peixes e as condições descritas contradizem equilíbrio ambiental.","E":"Os insetos e urubus não são apresentados como populações controladas."},"takeaway":"Leia paisagem como resultado das relações sociais e ambientais, não como cenário neutro.","key":"humanas:H558","area":"humanas","year":2023,"number":68,"answer":"C","subject":"Geografia","topic":"Cartografia, paisagem e tecnologias geográficas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Violência e ameaça à dignidade","steps":["As juízas são ameaçadas por sua atuação contra crimes e violência de gênero.","O quadro inclui medo, perseguição e risco à integridade física.","A categoria central é desrespeito à dignidade humana, D; descrever a violência não autoriza generalizar esse comportamento a toda uma população ou religião."],"alternatives":{"A":"A expressão é vaga e não identifica a violação de direitos das mulheres.","B":"O problema não é desprezo religioso por parte das vítimas.","C":"Falar só em normas morais oculta a violação concreta de direitos e segurança.","D":"Ameaças, abusos e perseguição negam dignidade e proteção às pessoas.","E":"Não se condena a quebra de uma hierarquia, mas uma situação de violência e opressão."},"takeaway":"Em direitos humanos, centre a análise nos direitos e práticas concretamente violados.","key":"humanas:H735","area":"humanas","year":2023,"number":69,"answer":"D","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A repressão é parte da organização do regime","steps":["O relato menciona morte sob repressão, jornalistas presos e medo de falar.","O silêncio imposto e a denúncia no funeral mostram o uso de instituições contra opositores.","C identifica mecanismos repressivos institucionalizados para eliminar resistências, não uma cerimônia estatal de propaganda."],"alternatives":{"A":"A poesia é usada pelos participantes para denunciar, não pelo regime para promover integração.","B":"O acontecimento evidencia repressão e medo, não apenas uma estratégia de propaganda.","C":"Prisões, violência e intimidação integram o aparato de enfrentamento à oposição.","D":"O funeral não é descrito como um cerimonial criado pelo governo para controlar participantes.","E":"O texto não fundamenta uma estatização geral dos meios de comunicação."},"takeaway":"Distinga manifestações de resistência dos mecanismos estatais contra os quais elas se dirigem.","key":"humanas:H126","area":"humanas","year":2023,"number":70,"answer":"C","subject":"História do Brasil","topic":"Ditadura Militar","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Grilagem abre caminho à apropriação","steps":["O autor critica uma explicação que atribui todo o desmatamento à soja.","Seu foco é o tripé de grileiros, madeireiros e pecuaristas, associado à especulação fundiária.","A apropriação de áreas devolutas, A, é o problema territorial central nesse encadeamento."],"alternatives":{"A":"A captura irregular de terras públicas conecta especulação, madeira e avanço de atividades.","B":"Sonegação pode ocorrer, mas não é o mecanismo central apresentado pelo autor.","C":"A frase sobre exportação ilegal não explica a apropriação territorial descrita.","D":"Desoneração tributária não aparece como a causa do tripé apontado.","E":"O trecho não atribui a causa principal a uma mudança específica da legislação ambiental."},"takeaway":"Grilagem não é simplesmente cultivar uma área: envolve apropriação irregular e disputa de domínio da terra.","key":"humanas:H305","area":"humanas","year":2023,"number":71,"answer":"A","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Otimismo tecnológico e crítica satírica","steps":["O Texto I destaca possíveis benefícios tecnológicos das viagens, expressando expectativa.","A charge contrapõe a fala pacífica dos bilionários a um alerta para não confiar neles.","As perspectivas são expectativa e desconfiança, respectivamente, B. Identificar a posição do autor não exige validar cada exemplo histórico usado por ele."],"alternatives":{"A":"O primeiro texto não destaca dependência e o segundo não expressa confiança no progresso.","B":"A promessa de benefícios e a advertência satírica sustentam a dupla expectativa/desconfiança.","C":"Angústia e adaptação não descrevem as posições contrastantes.","D":"A charge critica os agentes, sem afirmar apenas um retrocesso tecnológico.","E":"Receio não é a posição dominante do Texto I, nem civilidade a crítica do Texto II."},"takeaway":"Separe analisar uma tese de endossar como fato todas as alegações usadas para defendê-la.","key":"humanas:H698","area":"humanas","year":2023,"number":72,"answer":"B","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Construir navios exige madeira","steps":["O texto destaca consumo lenhoso e expansão da construção naval nos séculos XV e XVI.","A expansão marítima aumenta a demanda por embarcações e por madeira empregada em sua construção.","Esse acontecimento agrava diretamente a pressão sobre as florestas, A, sem recorrer a uma industrialização posterior como explicação exclusiva."],"alternatives":{"A":"A ampliação das navegações exige mais construção naval e, portanto, mais produtos florestais.","B":"O Renascimento cultural não é o vínculo material direto com a demanda naval destacada.","C":"Centralização política não explica com a mesma precisão o consumo de madeira descrito.","D":"Reformas religiosas não constituem o mecanismo direto indicado no trecho.","E":"O texto enfatiza transformações modernas, não a simples manutenção do feudalismo."},"takeaway":"Relacione o recurso natural aos usos materiais da atividade econômica no período correto.","key":"humanas:H192","area":"humanas","year":2023,"number":73,"answer":"A","subject":"História Geral","topic":"Idade Moderna: Renascimento, Reforma e absolutismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dominação política com acomodação religiosa","steps":["O império impõe tributos, lealdade e referências oficiais.","Ao mesmo tempo, grupos mantêm línguas e deuses locais junto ao culto imperial.","A coexistência mostra flexibilidade nos costumes religiosos, D, não ausência de dominação."],"alternatives":{"A":"Direitos humanos é uma categoria contemporânea que não descreve o arranjo analisado.","B":"Crenças coloniais é uma expressão inadequada para explicar a composição interna apresentada.","C":"O texto não avalia moralmente como tolerável o regime tributário.","D":"Manter deuses locais ao lado dos imperiais evidencia acomodação da diversidade religiosa.","E":"A coerção laboral aparece, mas não é o aspecto cultural de flexibilidade cobrado."},"takeaway":"Diversidade cultural pode persistir num império sem que isso elimine tributos, coerção ou hierarquia.","key":"humanas:H193","area":"humanas","year":2023,"number":74,"answer":"D","subject":"História Geral","topic":"Idade Moderna: Renascimento, Reforma e absolutismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reavaliar uma ofensa racializada","steps":["O movimento pede retirar um termo associado a uma história de inferiorização de pessoas negras.","A disputa é sobre normalizar essa expressão em cantos de torcida.","A proposta reflete condenação do preconceito racial, C, não uma medida especificamente relacionada a gênero ou sexualidade."],"alternatives":{"A":"O problema destacado é a carga racial da ofensa, não apenas sua origem numa elite.","B":"Misoginia se refere à inferiorização das mulheres, que não é o eixo do termo analisado.","C":"A revisão de um insulto racializado indica contestação ao preconceito racial.","D":"O texto não caracteriza uma prática homofóbica ou sua criminalização.","E":"Machismo não é a categoria específica da discriminação mencionada."},"takeaway":"Em linguagem discriminatória, identifique quem é inferiorizado e a história social da expressão.","key":"humanas:H003","area":"humanas","year":2023,"number":75,"answer":"C","subject":"História do Brasil","topic":"Brasil Colônia e povos indígenas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Fecundidade e participação social feminina","steps":["O gráfico apresenta queda de 6,3 para cerca de 1,5 filho por mulher.","A ampliação da participação feminina no trabalho remunerado integra mudanças sociais associadas à queda da fecundidade.","D é o fator listado pertinente; não é causa única nem prova de que todas as mulheres sigam o mesmo projeto de vida."],"alternatives":{"A":"O período não corresponde à legalização ampla do aborto no Brasil.","B":"Envelhecimento é principalmente consequência da transição demográfica, não o fator social pedido.","C":"Mais gravidez precoce não explica diretamente a redução do número de filhos.","D":"Participação no trabalho remunerado se associa a transformações na formação familiar e fecundidade.","E":"O gráfico não demonstra redução de benefícios de licença-maternidade como causa."},"takeaway":"Não confunda causas sociais da queda de fecundidade com seus efeitos na estrutura etária.","key":"humanas:H488","area":"humanas","year":2023,"number":76,"answer":"D","subject":"Geografia","topic":"Demografia e migrações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Saúde como responsabilidade de governo","steps":["O autor condena a demora em transmitir os benefícios da vacinação.","O contraste entre interesse no ouro e descaso pelos habitantes cobra uma obrigação pública.","E expressa a responsabilidade dos governantes pela saúde, sem transformar a vacinação em defesa do absolutismo."],"alternatives":{"A":"Não se investiga aqui uma lei observável da natureza ou seu método de descoberta.","B":"O texto critica o governo; não legitima um monarca como garantia de justiça.","C":"A liberdade fundada no direito natural não é o argumento específico do trecho.","D":"A riqueza proveniente da terra não é a tese da cobrança sobre vacinas.","E":"O governante deve promover condições de saúde em vez de negligenciar seus habitantes."},"takeaway":"Identifique a ideia iluminista efetivamente mobilizada, não apenas qualquer tema associado ao movimento.","key":"humanas:H213","area":"humanas","year":2023,"number":77,"answer":"E","subject":"História Geral","topic":"Iluminismo e revoluções burguesas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Agricultura também cabe na cidade","steps":["Moradores cultivam alimentos e encurtam a distância entre produção e consumo.","O plantio pode aproveitar espaços urbanos sem uso para essa finalidade.","A ocupação de lugares ociosos, A, é a vantagem espacial pertinente, não exportar mais ou adensar o centro."],"alternatives":{"A":"Hortas e outros cultivos podem dar função produtiva e alimentar a espaços ociosos.","B":"Plantar não implica necessariamente aumentar a densidade de construções ou moradores.","C":"O texto aproxima consumo local e produção, não prioriza mercados externos.","D":"Insumos químicos não são apresentados como condição ou vantagem desse cultivo.","E":"A agricultura urbana descrita não depende de mecanização intensiva."},"takeaway":"Observe a escala local de uma prática antes de lhe atribuir objetivos da agroindústria exportadora.","key":"humanas:H306","area":"humanas","year":2023,"number":78,"answer":"A","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Liberdade diante de uma situação dada","steps":["Gerineldo age como se o inventário do mundo esgotasse todas as possibilidades.","Em Sartre, a situação condiciona a existência, mas é vivida por uma liberdade que pode projetar-se além do dado.","O determinismo do personagem nega essa transcendência, B, sem que transcendência aqui signifique abandonar fisicamente o mundo."],"alternatives":{"A":"A oposição principal não envolve a teoria psicanalítica do inconsciente.","B":"Fechar todas as possibilidades no já previsto nega a superação livre da situação.","C":"Não se discute a difusão social do conhecimento como contraponto filosófico.","D":"A brevidade da vida não é o contraste expresso entre os dois textos.","E":"Evolução biológica não é o objeto da divergência apresentada."},"takeaway":"Na questão existencialista, transcendência designa projetar possibilidades a partir de uma situação concreta.","key":"humanas:H699","area":"humanas","year":2023,"number":79,"answer":"B","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reprimir e também cooptar organizações","steps":["O governo combate as Ligas, mas oferece formação conservadora a lideranças sindicais.","A aparente ambiguidade se explica pelo interesse em controlar a organização dos trabalhadores.","A intenção é conter tensões políticas, A, não promover uma reforma fundiária por meio desses cursos."],"alternatives":{"A":"Lideranças alinhadas ao regime ajudam a conter mobilização e conflito político.","B":"O foco do trecho é orientação política sindical, não uma alteração da legislação.","C":"Não se caracteriza o programa descrito como difusão de um projeto populista.","D":"Cursos de liderança não regularizam por si a propriedade da terra.","E":"A expansão da oferta de trabalhadores não é o objetivo explicitado pela estratégia."},"takeaway":"Cooptação e repressão podem operar juntas numa estratégia de controle político.","key":"humanas:H127","area":"humanas","year":2023,"number":80,"answer":"A","subject":"História do Brasil","topic":"Ditadura Militar","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O poder distribui tratamentos às ilegalidades","steps":["O texto distingue delitos acessíveis às classes populares de fraudes favorecidas pela posição burguesa.","Tribunais, penas e acordos são distribuídos de modo desigual entre esses circuitos.","A chave é a gestão das ilicitudes pelo sistema judicial, A, não uma justiça igualmente aplicada a todos."],"alternatives":{"A":"A seleção dos circuitos e das respostas judiciais administra diferentes ilegalidades.","B":"O próprio contraste entre castigos e acomodações nega um modelo equânime.","C":"O trecho não afirma que penas severas suprimem a criminalidade.","D":"Privilégios de classe não são apresentados como realização de justiça social.","E":"A oposição central é político-econômica e judicial, não uma hierarquia meramente cultural."},"takeaway":"Pergunte quem é punido, por quais práticas e com quais procedimentos: a lei não aparece isolada das relações sociais.","key":"humanas:H700","area":"humanas","year":2023,"number":81,"answer":"A","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cartas ligam sociedades de origem e destino","steps":["As correspondências levam notícias, dinheiro, conselhos e referências familiares.","Com isso, tradições são transmitidas e reconstruídas entre diferentes lugares.","O dispositivo permite circularidade cultural, B, sem ser descrito como aparato de fiscalização estatal."],"alternatives":{"A":"A comunicação familiar não é caracterizada como conflito entre nativos e estrangeiros.","B":"As cartas fazem circular experiências e referências entre partida e acolhimento.","C":"Não se descreve uma autoridade doutrinária controlando o conteúdo das cartas.","D":"O texto enfatiza redes pessoais, não inspeção política de fronteiras.","E":"As mensagens não são apresentadas como sistema de vigilância dos trabalhadores."},"takeaway":"Tecnologia de comunicação também sustenta vínculos afetivos e circulação cultural a longa distância.","key":"humanas:H489","area":"humanas","year":2023,"number":82,"answer":"B","subject":"Geografia","topic":"Demografia e migrações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A degradação compromete a fertilidade","steps":["Desmatamento, uso desordenado e poluentes prejudicam propriedades do solo.","A perda de nutrientes, matéria orgânica e condições favoráveis à vida reduz sua fertilidade.","C identifica o comprometimento produtivo que dificulta a recuperação; isso não significa que toda degradação seja irreversível."],"alternatives":{"A":"Mais biomassa pode favorecer a proteção do solo, não é a perda destacada.","B":"Reduzir salinização tende a favorecer, e não impedir, a recuperação.","C":"A diminuição da fertilidade compromete funções do solo e torna sua recuperação difícil.","D":"Ampliar microfauna benéfica não é o dano principal descrito.","E":"Decomposição não é, em si, sinônimo de degradação: pode reciclar nutrientes."},"takeaway":"Não trate todo processo biológico do solo como dano; diferencie fertilidade, salinização e decomposição.","key":"humanas:H307","area":"humanas","year":2023,"number":83,"answer":"C","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Economia de tempo e possibilidades de convívio","steps":["Equipamentos e organização doméstica buscam economizar movimentos e simplificar tarefas.","A redução do tempo exigido pelo trabalho doméstico pode abrir espaço para outras atividades.","D indica ampliação das possibilidades de socialização; isso não prova fim da desigualdade na divisão do trabalho."],"alternatives":{"A":"Economia de movimentos não implica que as mulheres passem a controlar todo o orçamento.","B":"Não se trata de mudança das crenças ou tradições religiosas.","C":"O acesso à representação política não decorre diretamente dos equipamentos descritos.","D":"Simplificar tarefas pode liberar tempo e ampliar oportunidades de convivência social.","E":"A especialização não é abolida; a racionalização reorganiza a execução das tarefas."},"takeaway":"Uma tecnologia pode ampliar possibilidades sem garantir automaticamente emancipação ou igualdade.","key":"humanas:H103","area":"humanas","year":2023,"number":84,"answer":"D","subject":"História do Brasil","topic":"Era Vargas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Interesses diferentes diante de um mesmo acordo","steps":["Agricultores temem concorrer com produtos sul-americanos de menor custo.","Industriais querem ampliar o acesso comercial a esses mercados.","D combina preservação de barreiras fitossanitárias e livre circulação de mercadorias, respectivamente."],"alternatives":{"A":"Fluxos migratórios e sindicatos não são os eixos dos interesses apresentados.","B":"A oposição agrícola não se resume a leis trabalhistas, nem a indústria pede só importações.","C":"A preocupação central dos dois setores é comercial; transferência tecnológica não é a demanda citada.","D":"Proteções sanitárias podem resguardar agricultores, enquanto abertura comercial beneficia industriais exportadores.","E":"Remover barreiras é contrário à posição agrícola descrita; salários não são a demanda industrial."},"takeaway":"Em itens com respectivamente, confira separadamente a posição de cada grupo e a ordem solicitada.","key":"humanas:H360","area":"humanas","year":2023,"number":85,"answer":"D","subject":"Geografia","topic":"Geopolítica e globalização","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Autonomia intelectual contraria papéis impostos","steps":["A educação cultiva julgamento independente e opiniões próprias em Anaïs.","O narrador contrasta tais qualidades com o ideal de mulher modesta destinada ao lar.","O comportamento rompe valores institucionalizados, E, em vez de aceitar a hierarquia de gênero."],"alternatives":{"A":"A independência intelectual não é descrita como abandono de relações afetivas.","B":"A personagem desenvolve opinião própria, não nega a subjetividade.","C":"A tensão decorre justamente de ela contrariar o lugar feminino esperado.","D":"A passagem não apresenta seu comportamento como reforço da estratificação.","E":"As qualidades cultivadas desafiam os papéis e expectativas sociais de gênero."},"takeaway":"Atente ao contraste entre a voz normativa do narrador e o comportamento da personagem.","key":"humanas:H214","area":"humanas","year":2023,"number":86,"answer":"E","subject":"História Geral","topic":"Iluminismo e revoluções burguesas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A xenofobia se combina ao anticomunismo","steps":["Os textos situam a busca de refúgio e a suspeita contra imigrantes.","Concorrência por trabalho e riqueza se soma ao temor de anarquismo e comunismo.","B reúne os fundamentos socioeconômicos e ideológicos dessa hostilidade, sem reduzi-la exclusivamente à religião."],"alternatives":{"A":"A identidade judaica importa, mas o trecho explica a suspeita também por trabalho e política.","B":"Temor econômico e rejeição de doutrinas políticas fundamentam o tratamento descrito.","C":"A passagem não faz da alfândega ou da delimitação territorial o fundamento central.","D":"Não são citados dispositivos constitucionais como explicação principal do preconceito.","E":"Os argumentos expostos não decorrem de decretos internacionais específicos."},"takeaway":"Uma perseguição pode articular preconceitos religiosos, interesses econômicos e disputas ideológicas.","key":"humanas:H104","area":"humanas","year":2023,"number":87,"answer":"B","subject":"História do Brasil","topic":"Era Vargas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Competir sem limites éticos","steps":["O autor distingue concorrência com regras de competitividade em que vale tudo.","Dumping comercial envolve vender a preços artificialmente baixos em prática desleal para prejudicar concorrentes.","A é o exemplo compatível com a condenação, não qualquer mudança na estrutura de uma empresa."],"alternatives":{"A":"O dumping é uma prática desleal que pode eliminar concorrentes e desequilibrar a disputa.","B":"Reunir funções administrativas não implica por si violação moral na concorrência.","C":"Uma holding é uma forma de organização societária, não necessariamente uma prática desleal.","D":"Limitar monopólios pode favorecer concorrência, em vez de abolir seus limites éticos.","E":"Modernizar processos não significa, por si, recorrer a práticas de guerra comercial."},"takeaway":"Diferencie uma estrutura empresarial de uma conduta específica que prejudica a concorrência.","key":"humanas:H622","area":"humanas","year":2023,"number":88,"answer":"A","subject":"Filosofia","topic":"Ética e filosofia política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mitigar a causa do aquecimento","steps":["Os mapas simulam aquecimento e alterações de chuva em cenários de maior temperatura.","Reduzir emissões de gases de efeito estufa atua sobre a intensificação antrópica do aquecimento.","Controlar emissões de carbono, D, é a medida de mitigação; monitorar ou migrar não reduz diretamente essa causa."],"alternatives":{"A":"Expandir transporte marítimo não garante redução de emissões e pode ampliá-las.","B":"Migrar pode ser uma resposta a impactos, mas não controla a causa das mudanças simuladas.","C":"Monitoramento vulcânico não é controle das emissões humanas que intensificam o aquecimento.","D":"Reduzir emissões de carbono contribui para limitar o aquecimento e seus efeitos.","E":"Termoelétricas movidas a combustíveis fósseis podem ampliar emissões, não mitigá-las."},"takeaway":"Mitigação reduz causas; adaptação lida com efeitos. A pergunta pede reduzir as mudanças projetadas.","key":"humanas:H269","area":"humanas","year":2023,"number":89,"answer":"D","subject":"Geografia","topic":"Meio ambiente e problemas ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ornamentar o discurso não é aprofundar o saber","steps":["Brás Cubas admite decorar fórmulas e frases para usar em conversação.","O saber aparece como aparência verbal e recurso de apresentação de si.","B corresponde ao uso persuasivo do discurso, aproximado no item da crítica antiga aos sofistas; não é uma descrição exaustiva de todos eles."],"alternatives":{"A":"O personagem admite conservar a casca verbal, não elaborar conceitos em profundidade.","B":"Frases e referências servem à atuação discursiva, mais que à investigação dos conteúdos.","C":"O trecho não descreve a recitação épica de rapsodos.","D":"Não há observação empírica da natureza como objetivo do personagem.","E":"Expressão pictográfica diz respeito a imagens, não ao uso ornamentado da fala."},"takeaway":"Não confunda domínio de vocabulário erudito com compreensão conceitual do que ele designa.","key":"humanas:H644","area":"humanas","year":2023,"number":90,"answer":"B","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2023_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2023.pdf","sha256":"d01f0ca9e0855b69428cf0942585259d046a2d63706568fa73a1efefb760d5c1","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2023.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
